// THE API, HTTP-shaped and free of any server: handle(store, { method, path, tenant, today, body }) -> { status, body }.
// `tenant` is the library system the caller signed in as -- the gateway in front of the service sets it -- and `today`
// the day the service's clock says it is. A refusal answers { error: <word> }.
import { isDay } from "./dates.mjs";
import { isKey } from "./store.mjs";
import { allMine, isTenant, mine } from "./tenancy.mjs";
import { copyView, isFormat, newCopy, newTitle, titleView } from "./catalog.mjs";
import { memberView, newMember } from "./members.mjs";
import { lendRefusal, lent, loanView, renewed, renewRefusal, returned } from "./loans.mjs";
import { holdView, newHold, noticeView, openHoldOf } from "./holds.mjs";

const answer = (status, body) => ({ status, body });

const refused = (status, error) => answer(status, { error });

const found = (record, error, view) => (record ? answer(200, view(record)) : refused(404, error));

const isName = (v) => typeof v === "string" && v.trim().length > 0 && v.length <= 200;

const isCents = (v) => Number.isInteger(v) && v >= 0 && v <= 10000000;

// ---- the catalogue and the members ------------------------------------------------------------------------------------

const titleAdded = (c) => (isName(c.body.name) && isFormat(c.body.format) ? answer(201, titleView(newTitle(c.store, c.tenant, c.body))) : refused(400, "bad-title"));

const copyOfTitle = (c, title) => (title ? answer(201, copyView(newCopy(c.store, c.tenant, title, c.body))) : refused(404, "no-title"));

const copyAdded = (c) => (isKey(c.body.title) && isCents(c.body.replacementCents) ? copyOfTitle(c, mine(c.store, c.tenant, "titles", c.body.title)) : refused(400, "bad-copy"));

const memberAdded = (c) => (isName(c.body.name) ? answer(201, memberView(newMember(c.store, c.tenant, c.body))) : refused(400, "bad-member"));

const noticesOf = (c, member) => answer(200, { notices: allMine(c.store, c.tenant, "notices").filter((n) => n.member === member.id).map(noticeView) });

const notices = (c, [id]) => ((m) => (m ? noticesOf(c, m) : refused(404, "no-member")))(mine(c.store, c.tenant, "members", id));

// ---- lending, returns and renewals ------------------------------------------------------------------------------------

const lendOrNot = (c, copy, member) => ((why) => (why ? refused(409, why) : answer(201, loanView(lent(c.store, c.tenant, copy, member, c.today)))))(lendRefusal(c.store, c.tenant, copy, member));

function lend(c) {
  const copy = mine(c.store, c.tenant, "copies", c.body.copy);
  const member = mine(c.store, c.tenant, "members", c.body.member);
  if (!copy || !member) return refused(404, copy ? "no-member" : "no-copy");
  return lendOrNot(c, copy, member);
}

const loanOf = (c, id) => mine(c.store, c.tenant, "loans", id);

const giveBack = (c, loan) => (loan.returned ? refused(409, "returned") : answer(200, loanView(returned(c.store, c.tenant, loan, c.today))));

const back = (c, [id]) => ((loan) => (loan ? giveBack(c, loan) : refused(404, "no-loan")))(loanOf(c, id));

const renewOrNot = (c, loan) => ((why) => (why ? refused(409, why) : answer(200, loanView(renewed(c.store, c.tenant, loan)))))(renewRefusal(c.store, c.tenant, loan, c.today));

const renew = (c, [id]) => ((loan) => (loan ? renewOrNot(c, loan) : refused(404, "no-loan")))(loanOf(c, id));

// ---- holds ------------------------------------------------------------------------------------------------------------

const holdOrNot = (c, title, member) => (openHoldOf(c.store, c.tenant, title, member) ? refused(409, "duplicate-hold") : answer(201, holdView(newHold(c.store, c.tenant, title, member, c.today))));

function hold(c) {
  const title = mine(c.store, c.tenant, "titles", c.body.title);
  const member = mine(c.store, c.tenant, "members", c.body.member);
  if (!title || !member) return refused(404, title ? "no-member" : "no-title");
  return holdOrNot(c, title, member);
}

// ---- the routes -------------------------------------------------------------------------------------------------------

const ROUTES = [
  ["GET", /^\/titles$/, (c) => answer(200, { titles: allMine(c.store, c.tenant, "titles").map(titleView) })],
  ["POST", /^\/titles$/, titleAdded],
  ["GET", /^\/titles\/([^/]+)$/, (c, [id]) => found(mine(c.store, c.tenant, "titles", id), "no-title", titleView)],
  ["POST", /^\/copies$/, copyAdded],
  ["GET", /^\/copies\/([^/]+)$/, (c, [id]) => found(mine(c.store, c.tenant, "copies", id), "no-copy", copyView)],
  ["POST", /^\/members$/, memberAdded],
  ["GET", /^\/members\/([^/]+)$/, (c, [id]) => found(mine(c.store, c.tenant, "members", id), "no-member", memberView)],
  ["GET", /^\/members\/([^/]+)\/notices$/, notices],
  ["POST", /^\/loans$/, lend],
  ["GET", /^\/loans\/([^/]+)$/, (c, [id]) => found(loanOf(c, id), "no-loan", loanView)],
  ["POST", /^\/loans\/([^/]+)\/return$/, back],
  ["POST", /^\/loans\/([^/]+)\/renew$/, renew],
  ["POST", /^\/holds$/, hold],
  ["GET", /^\/holds\/([^/]+)$/, (c, [id]) => found(mine(c.store, c.tenant, "holds", id), "no-hold", holdView)],
];

const routed = (req) => ROUTES.map(([method, path, run]) => ({ run, m: method === req.method ? path.exec(String(req.path)) : null })).find((r) => r.m) ?? null;

const bodyOf = (req) => (req.body && typeof req.body === "object" && !Array.isArray(req.body) ? req.body : {});

export function handle(store, req) {
  if (!isTenant(req?.tenant)) return refused(401, "no-tenant");
  if (!isDay(req.today)) return refused(400, "bad-day");
  const r = routed(req);
  return r ? r.run({ store, tenant: req.tenant, today: req.today, body: bodyOf(req) }, r.m.slice(1)) : refused(404, "no-route");
}
// THE CATALOGUE: the titles a library system lends and the copies it holds of each. A title's format says how long a
// copy may stay out -- three weeks for a book, one week for a DVD -- and a copy is on the shelf or on loan.
import { created, put } from "./store.mjs";
import { mine } from "./tenancy.mjs";

export const LOAN_DAYS = { book: 21, dvd: 7 };

export const isFormat = (v) => typeof v === "string" && Object.hasOwn(LOAN_DAYS, v);

export const newTitle = (store, tenant, b) => created(store, "titles", "title", { tenant, name: b.name, format: b.format });

export const newCopy = (store, tenant, title, b) => created(store, "copies", "copy", { tenant, title: title.id, replacementCents: b.replacementCents, status: "shelf" });

// The title a copy is of: always one of the copy's own library system.
export const titleOfCopy = (store, copy) => mine(store, copy.tenant, "titles", copy.title);

export const loanDaysOf = (title) => LOAN_DAYS[title.format];

export const shelved = (store, copy) => put(store, "copies", { ...copy, status: "shelf" });

export const titleView = (t) => ({ id: t.id, name: t.name, format: t.format, loanDays: loanDaysOf(t) });

export const copyView = (c) => ({ id: c.id, title: c.title, replacementCents: c.replacementCents, status: c.status });
// DAYS. A loan goes out, falls due and comes back on a calendar day, never at a time of day, so every date here is an
// ISO day (YYYY-MM-DD) read in UTC: the same day wherever the service runs.
const DAY_MS = 86400000;

const SHAPE = /^\d{4}-\d{2}-\d{2}$/;

const msOf = (day) => Date.parse(`${day}T00:00:00Z`);

const dayAt = (ms) => new Date(ms).toISOString().slice(0, 10);

// A real day of the calendar: 2026-02-30 is not one.
export const isDay = (v) => typeof v === "string" && SHAPE.test(v) && Number.isFinite(msOf(v)) && dayAt(msOf(v)) === v;

export const addDays = (day, n) => dayAt(msOf(day) + n * DAY_MS);

// Whole days from one day to another: 0 for the same day, negative when `to` comes first.
export const daysBetween = (from, to) => Math.round((msOf(to) - msOf(from)) / DAY_MS);
// THE DROP BOX: the return box outside each library scans what is dropped into it and sends one message per item, which
// this consumer checks in -- the same check-in as at the desk, on the day the box scanned it. Every message is
// acknowledged once it is done with, and one delivered again is acknowledged and changes nothing.
//
//   consume(store, { id, tenant, copy, at }) -> { ack: true, outcome }
//   outcome: returned · not-on-loan · unknown-copy · duplicate · rejected (a message this consumer cannot read)
import { isDay } from "./dates.mjs";
import { get, isKey, put } from "./store.mjs";
import { isTenant, mine } from "./tenancy.mjs";
import { openLoanOfCopy, returned } from "./loans.mjs";

const wellFormed = (m) => Boolean(m) && isKey(m.id) && isTenant(m.tenant) && isKey(m.copy) && isDay(m.at);

const done = (store, m, outcome) => (put(store, "deliveries", { id: m.id, seq: 0, tenant: m.tenant, outcome }), { ack: true, outcome });

function checkedIn(store, m) {
  const copy = mine(store, m.tenant, "copies", m.copy);
  const loan = copy ? openLoanOfCopy(store, copy.tenant, copy) : null;
  if (!loan) return done(store, m, copy ? "not-on-loan" : "unknown-copy");
  returned(store, copy.tenant, loan, m.at);
  return done(store, m, "returned");
}

export function consume(store, message) {
  if (!wellFormed(message)) return { ack: true, outcome: "rejected" };
  if (get(store, "deliveries", message.id)) return { ack: true, outcome: "duplicate" };
  return checkedIn(store, message);
}
// HOLDS: members waiting for a title, in the order they asked.
import { created } from "./store.mjs";
import { allMine } from "./tenancy.mjs";

// A title's holds, in the order they were placed.
const holdsOn = (store, tenant, titleId) => allMine(store, tenant, "holds").filter((h) => h.title === titleId);

export const openHoldOf = (store, tenant, title, member) => holdsOn(store, tenant, title.id).find((h) => h.member === member.id && h.state === "waiting") ?? null;

export const newHold = (store, tenant, title, member, day) => created(store, "holds", "hold", { tenant, title: title.id, member: member.id, placed: day, state: "waiting", copy: null, pickupBy: null });

// Whether anybody is waiting for a copy's title.
export const holdWaiting = (store, copy) => holdsOn(store, copy.tenant, copy.title).some((h) => h.state === "waiting");

export const holdView = (h) => ({ id: h.id, title: h.title, member: h.member, placed: h.placed, state: h.state, copy: h.copy, pickupBy: h.pickupBy });

export const noticeView = (n) => ({ id: n.id, kind: n.kind, hold: n.hold, copy: n.copy, pickupBy: n.pickupBy });
// LOANS: a copy lent to a member until its due date, renewed, and brought back -- at the desk, or through the drop box
// (dropbox.mjs). A late return is fined and the fine charged to the member, and the copy goes back on the shelf.
import { addDays } from "./dates.mjs";
import { created, put } from "./store.mjs";
import { allMine, mine } from "./tenancy.mjs";
import { loanDaysOf, shelved, titleOfCopy } from "./catalog.mjs";
import { charged, LOAN_LIMIT } from "./members.mjs";
import { fineFor } from "./fines.mjs";
import { holdWaiting } from "./holds.mjs";

export const RENEWALS = 2;

const openLoansOf = (store, tenant, member) => allMine(store, tenant, "loans").filter((l) => l.member === member.id && !l.returned);

// Why a copy may not be lent to a member now, asked in order; none, and it may.
const LEND_REFUSALS = [
  { error: "not-available", when: (c) => c.copy.status === "loan" },
  { error: "limit", when: (c) => openLoansOf(c.store, c.tenant, c.member).length >= LOAN_LIMIT },
];

export const lendRefusal = (store, tenant, copy, member) => LEND_REFUSALS.find((r) => r.when({ store, tenant, copy, member }))?.error ?? null;

const dueOf = (store, copy, day) => addDays(day, loanDaysOf(titleOfCopy(store, copy)));

export function lent(store, tenant, copy, member, day) {
  put(store, "copies", { ...copy, status: "loan" });
  return created(store, "loans", "loan", { tenant, copy: copy.id, member: member.id, out: day, due: dueOf(store, copy, day), renewals: 0, returned: null, fineCents: 0 });
}

// A loan brought back on a day: fined for the days it is late and the fine charged to its member, and its copy shelved.
export function returned(store, tenant, loan, day) {
  const copy = mine(store, tenant, "copies", loan.copy);
  const fineCents = fineFor(titleOfCopy(store, copy), copy, loan.due, day);
  charged(store, mine(store, tenant, "members", loan.member), fineCents);
  shelved(store, copy);
  return put(store, "loans", { ...loan, returned: day, fineCents });
}

export const openLoanOfCopy = (store, tenant, copy) => allMine(store, tenant, "loans").find((l) => l.copy === copy.id && !l.returned) ?? null;

// Why a loan may not be renewed on a day, asked in order; none, and it may.
const RENEW_REFUSALS = [
  { error: "returned", when: (r) => r.loan.returned !== null },
  { error: "overdue", when: (r) => r.day > r.loan.due },
  { error: "renewal-limit", when: (r) => r.loan.renewals >= RENEWALS },
  { error: "hold-waiting", when: (r) => holdWaiting(r.store, r.copy) },
];

const copyOfLoan = (store, tenant, loan) => mine(store, tenant, "copies", loan.copy);

export const renewRefusal = (store, tenant, loan, day) => RENEW_REFUSALS.find((r) => r.when({ store, loan, day, copy: copyOfLoan(store, tenant, loan) }))?.error ?? null;

// A renewal moves the due date on by the title's loan period, counted from the due date it had.
export const renewed = (store, tenant, loan) => put(store, "loans", { ...loan, due: addDays(loan.due, loanDaysOf(titleOfCopy(store, copyOfLoan(store, tenant, loan)))), renewals: loan.renewals + 1 });

export const loanView = (l) => ({ id: l.id, copy: l.copy, member: l.member, out: l.out, due: l.due, renewals: l.renewals, returned: l.returned, fineCents: l.fineCents });
// MEMBERS of a library system: who may borrow, and what they owe -- the fines their late returns were charged, added up.
// A member may have five items out at once.
import { created, put } from "./store.mjs";

export const LOAN_LIMIT = 5;

export const newMember = (store, tenant, b) => created(store, "members", "member", { tenant, name: b.name, balanceCents: 0 });

export const charged = (store, member, cents) => put(store, "members", { ...member, balanceCents: member.balanceCents + cents });

export const memberView = (m) => ({ id: m.id, name: m.name, balanceCents: m.balanceCents });
// THE STORE: every record one JSON file, written whole and renamed into place, so a service that stops and starts again
// finds exactly what it kept. Every library system's records share it: a record says the `tenant` it belongs to, and
// every id comes from one counter, so no two records ever share one -- in one system or across them.
//
//   openStore(dir) -> store            put(store, kind, record) -> record       get(store, kind, id) -> record | null
//   list(store, kind) -> [record], in the order they were made      created(store, kind, prefix, fields) -> record
import { existsSync, mkdirSync, readdirSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const KEY = /^[A-Za-z0-9][A-Za-z0-9-]{0,63}$/;

// What an id may be: letters, digits and dashes -- never a path.
export const isKey = (v) => typeof v === "string" && KEY.test(v);

export const openStore = (dir) => (mkdirSync(dir, { recursive: true }), { dir });

const fileOf = (store, kind, id) => join(store.dir, kind, `${id}.json`);

const readJson = (file) => JSON.parse(readFileSync(file, "utf8"));

function writeWhole(file, value) {
  writeFileSync(`${file}.tmp`, `${JSON.stringify(value, null, 2)}\n`);
  renameSync(`${file}.tmp`, file);
}

export function put(store, kind, record) {
  mkdirSync(join(store.dir, kind), { recursive: true });
  writeWhole(fileOf(store, kind, record.id), record);
  return record;
}

export const get = (store, kind, id) => (isKey(id) && existsSync(fileOf(store, kind, id)) ? readJson(fileOf(store, kind, id)) : null);

const bySeq = (a, b) => a.seq - b.seq;

const namesIn = (dir) => (existsSync(dir) ? readdirSync(dir).filter((n) => n.endsWith(".json")) : []);

export const list = (store, kind) => namesIn(join(store.dir, kind)).map((n) => readJson(join(store.dir, kind, n))).sort(bySeq);

function nextSeq(store) {
  const file = join(store.dir, "counter.json");
  const n = (existsSync(file) ? readJson(file).n : 0) + 1;
  writeWhole(file, { n });
  return n;
}

// A new record of a kind: its id from the one counter, and its place in the order records were made (`seq`).
export const created = (store, kind, prefix, fields) => ((n) => put(store, kind, { ...fields, id: `${prefix}-${n}`, seq: n }))(nextSeq(store));
// A LIBRARY SYSTEM's own records. One service holds every system's, and each system sees, lists and changes only its
// own: a record of another system reads exactly as one that does not exist.
import { get, list } from "./store.mjs";

const TENANT = /^[a-z][a-z0-9-]{0,31}$/;

// What a library system's name may be, as the gateway in front of the service hands it.
export const isTenant = (v) => typeof v === "string" && TENANT.test(v);

const ownedBy = (tenant) => (r) => (r && r.tenant === tenant ? r : null);

export const mine = (store, tenant, kind, id) => ownedBy(tenant)(get(store, kind, id));

export const allMine = (store, tenant, kind) => list(store, kind).filter((r) => r.tenant === tenant);
# lending

A lending service for library systems. Several library systems share one service, and each sees and changes only its
own records. Records live on disk, one JSON file each, so a service that stops and starts again finds them.

- `src/dates.mjs` — calendar days (`YYYY-MM-DD`, UTC).
- `src/store.mjs` — the durable store: `openStore(dir)`.
- `src/tenancy.mjs` — a library system's own records.
- `src/catalog.mjs` — titles and their copies. A book may be out for 21 days, a DVD for 7.
- `src/members.mjs` — members, and what they owe. A member may have five items out at once.
- `src/loans.mjs` — lending, renewals and returns.
- `src/fines.mjs` — fines for late returns.
- `src/holds.mjs` — holds: members waiting for a title.
- `src/api.mjs` — the HTTP-shaped API: `handle(store, { method, path, tenant, today, body }) -> { status, body }`.
- `src/dropbox.mjs` — the drop box consumer: `consume(store, { id, tenant, copy, at }) -> { ack, outcome }`.

`tenant` is the library system the caller signed in as, and `today` the day the service's clock says it is. A refusal
answers `{ error: <word> }`.

| Route | Does |
|---|---|
| `POST /titles` `{ name, format }` · `GET /titles` · `GET /titles/:id` | adds a title (`book` or `dvd`), the system's titles, a title |
| `POST /copies` `{ title, replacementCents }` | adds a copy of a title |
| `GET /copies/:id` | a copy and its status: `shelf` or `loan` |
| `POST /members` `{ name }` · `GET /members/:id` | adds a member, a member |
| `GET /members/:id/notices` | the notices a member was sent |
| `POST /loans` `{ copy, member }` · `GET /loans/:id` | lends a copy to a member, a loan |
| `POST /loans/:id/return` | checks a loan in at the desk |
| `POST /loans/:id/renew` | renews a loan |
| `POST /holds` `{ title, member }` · `GET /holds/:id` | places a hold on a title, a hold |

`npm test` runs the tests.

